.bk-button.primary { border-color: var(--bk-indigo); background: var(--bk-indigo); color: white; box-shadow: rgba(124, 58, 237, 0.125) 0px 4px 10px; }
.bk-icon { width: 34px; padding: 6px; flex: 0 0 auto; }
.bk-dashboard-toolbar, .bk-tools { display: flex; align-items: center; gap: 10px; flex-shrink: 0; min-width: 0px; }
.bk-dashboard-toolbar { padding: 5px 0px 2px; }
.bk-team { display: flex; align-items: center; gap: 10px; flex: 1 1 0%; }
.bk-team b, .bk-team small { display: block; }
.bk-team b { font-size: 12px; }
.bk-team small { margin-top: 2px; color: var(--bk-muted); font-size: 10px; }
.bk-avatar { display: inline-grid; place-items: center; width: 36px; height: 36px; flex: 0 0 auto; border-radius: 50%; background: linear-gradient(145deg, rgb(238, 232, 255), rgb(228, 233, 255)); border: 2px solid var(--bk-card); color: rgb(124, 58, 237); font-size: 11px; font-weight: 700; }
.bk-search { display: flex; align-items: center; gap: 10px; min-width: 200px; width: min(340px, 100%); height: 38px; padding: 0px 12px; border: 1px solid var(--bk-line); border-radius: 9px; background: var(--bk-card); color: var(--bk-muted); box-shadow: rgba(15, 23, 42, 0.03) 0px 1px 2px; transition: border-color 0.18s, box-shadow 0.18s; }
.bk-search input { flex: 1 1 0%; width: 100%; min-width: 0px; outline: none; border: 0px; background: transparent; color: var(--bk-text); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 13px; }
.bk-search input::placeholder { color: var(--bk-muted); }
.bk-tab-scroll { min-height: 0px; flex: 1 1 0%; overflow: auto; overscroll-behavior: contain; padding: 1px 2px 8px; }
.bk-workspace .custom-scrollbar, .bk-public .custom-scrollbar, .bk-dialog .custom-scrollbar { scrollbar-width: thin; scrollbar-color: rgb(217, 214, 236) transparent; overscroll-behavior: contain; }
.bk-page-stack { display: flex; flex-direction: column; gap: 11px; }
.bk-booking-card { display: flex; align-items: center; gap: 14px; min-height: 85px; border: 1px solid var(--bk-line); border-inline-start: 3px solid var(--booking-color,#7C3AED); border-radius: 11px; background: var(--bk-card); padding: 15px 17px; box-shadow: rgba(21, 34, 68, 0.01) 0px 2px 4px; }
.bk-booking-card-main { flex: 1 1 0%; min-width: 0px; }
.bk-title-link, .bk-name-link { padding: 0px; border: 0px; background: transparent; color: var(--bk-indigo); text-align: start; overflow-wrap: anywhere; font-size: 12px !important; font-weight: 600 !important; }
.bk-booking-card-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 13px; margin-top: 7px; color: var(--bk-muted); font-size: 10px; }
.bk-booking-card-meta > span { display: inline-flex; align-items: center; gap: 5px; }
.bk-platform { padding: 2px 7px; border-radius: 6px; background: rgb(246, 247, 250); }
.bk-card-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.bk-pill { display: inline-flex; align-items: center; justify-content: center; gap: 4px; max-width: max-content; padding: 3px 8px; border: 1px solid rgb(237, 233, 254); border-radius: 7px; background: var(--bk-soft); color: rgb(124, 58, 237); font-size: 10px; line-height: 1.4; white-space: nowrap; }
.bk-tab-footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: var(--bk-muted); font-size: 10px; flex-shrink: 0; padding: 5px 2px; }
.bk-tab-footer > span { display: inline-flex; align-items: center; gap: 4px; }
.dark .bk-workspace, .dark .bk-public, .dark .bk-dialog, .dark .bk-menu { --bk-bg: #151724; --bk-card: #1c2030; --bk-text: #e6e9f2; --bk-muted: #979fb5; --bk-line: #30354a; --bk-soft: #302b4c; --bk-indigo: #A78BFA; }
.dark .bk-builder-bar, .dark .bk-question, .dark .bk-location-options label, .dark .bk-radio-options label, .dark .bk-platform, .dark .bk-table th, .dark .bk-booking-card.off, .dark .bk-segmented { background: rgb(36, 40, 57); }
.bk-button, .bk-icon { transition: none; }
.commerce-select { display: block; min-width: 0px; width: 100%; }
.commerce-select-trigger { display: flex; align-items: center; gap: 8px; width: 100%; min-width: 0px; min-height: 36px; border: 1px solid rgb(203, 213, 225); border-radius: 8px; padding: 8px 12px; background: rgb(255, 255, 255); color: rgb(30, 41, 59); font-style: inherit; font-variant: inherit; font-stretch: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 13px; font-weight: 500; line-height: 1.4; text-align: start; box-shadow: rgba(15, 23, 42, 0.024) 0px 1px 2px; cursor: pointer; transition: border-color 0.15s, box-shadow 0.15s, background 0.15s; }
.commerce-select-trigger > span:first-of-type { display: block; flex: 1 1 0%; min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.commerce-select-leading-icon, .commerce-select-chevron { flex: 0 0 auto; color: rgb(100, 116, 139); }
.commerce-select-chevron { display: grid; place-items: center; margin-inline-start: auto; transition: transform 0.18s; }
.commerce-select-trigger, .commerce-select-chevron { transition: none; }
.lp-static-document.dark .commerce-select-trigger { background: rgb(23, 32, 51); border-color: rgb(71, 85, 105); color: rgb(226, 232, 240); }
.pp-page .pp-select .commerce-select-trigger { font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 11px; min-height: 36px; padding: 8px 10px; border-radius: 8px; border-color: rgb(203, 213, 225); background: rgb(255, 255, 255); }
.pp-page .pp-select .commerce-select-trigger > .commerce-select-chevron { display: grid; padding: 0px; }
.lp-static-document.dark .pp-page .pp-select .commerce-select-trigger { background: rgb(23, 32, 51); border-color: rgb(71, 85, 105); color: rgb(226, 232, 240); }
.pp-metrics { grid-template-columns: repeat(4, minmax(0px, 1fr)); }
.pp-page, .cw-page.tw-page, .cp-preview.cp-service, .cp-preview.cp-digital, .cp-preview.cp-course { background: linear-gradient(135deg, rgb(248, 250, 252) 0%, rgb(238, 242, 255) 55%, rgb(250, 245, 255) 100%); }
[data-sonner-toaster][dir="ltr"], .lp-static-document[dir="ltr"] { --toast-icon-margin-start: -3px; --toast-icon-margin-end: 4px; --toast-svg-margin-start: -1px; --toast-svg-margin-end: 0px; --toast-button-margin-start: auto; --toast-button-margin-end: 0; --toast-close-button-start: 0; --toast-close-button-end: unset; --toast-close-button-transform: translate(-35%, -35%); }
[data-sonner-toaster][dir="rtl"], .lp-static-document[dir="rtl"] { --toast-icon-margin-start: 4px; --toast-icon-margin-end: -3px; --toast-svg-margin-start: 0px; --toast-svg-margin-end: -1px; --toast-button-margin-start: 0; --toast-button-margin-end: auto; --toast-close-button-start: unset; --toast-close-button-end: 0; --toast-close-button-transform: translate(35%, -35%); }
